            if (shouldIgnoreCaption(event.text || '')) return;

            const payload = {
                meetingId: event.meetingId || meetingId,
                speakerId: event.speakerId || userId,
                utteranceId: event.utteranceId,
                isFinal: true,
                text: event.text,
                start: event.start,
