            workerRef.current.onmessage = (event) => {
                const {
                    type,
                    segments,
                    meetingId: mid,
                    status,
                    error,
                    chunkId,
                    chunkCreatedAt,
                    chunkDuration,
                    processingTime,
                    realtimeFactor,
                    droppedChunkCount
